const p = msg.payload;
const u = p?.uplink_message;
const decoded = u?.decoded_payload;

if (
    !u ||
    !decoded ||
    !Number.isInteger(u.f_cnt) ||
    !Number.isFinite(Number(decoded.rainlevel)) ||
    !p.received_at
) {
    node.warn("Ungültiger Regen-Uplink ignoriert");
    return null;
}

const device = p.end_device_ids?.device_id;
if (!device) {
    node.warn("Uplink ohne device_id ignoriert");
    return null;
}

// UTC-Empfangszeitpunkt übernehmen
const timestamp = Date.parse(p.received_at);
if (!Number.isFinite(timestamp)) {
    node.warn("Ungültiger received_at-Zeitstempel");
    return null;
}

// Regenmenge dieses Uplinks berechnen
const tip_count = Number(decoded.rainlevel);
const rain_mm = Math.round(tip_count * 0.5 * 10) / 10;

// InfluxDB 1.x: Felder und Tags
msg.measurement = "plantage_rain";
msg.payload = [
    {
        tip_count: tip_count,
        rain_mm: rain_mm,
        frame_counter: u.f_cnt
    },
    {
        device_id: device
    }
];

msg.timestamp = timestamp;

return msg;

const now = new Date();

// Lokales Datum und Stunde in Europe/Berlin ermitteln
const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/Berlin",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    hourCycle: "h23"
}).formatToParts(now);

const get = name => parts.find(p => p.type === name).value;

let year = Number(get("year"));
let month = Number(get("month"));
let day = Number(get("day"));
const hour = Number(get("hour"));

// Vor 08:00 Uhr gehört der Zeitraum zum Vortag
if (hour < 8) {
    const d = new Date(Date.UTC(year, month - 1, day - 1));
    year = d.getUTCFullYear();
    month = d.getUTCMonth() + 1;
    day = d.getUTCDate();
}

// Lokalen Tagesbeginn 08:00 Uhr als ISO-Zeitpunkt umrechnen.
// Die UTC-Verschiebung wird anhand Europe/Berlin bestimmt.
function berlinToUtc(y, m, d, h) {
    const target = Date.UTC(y, m - 1, d, h);
    const approx = new Date(target);

    const formatted = new Intl.DateTimeFormat("en-GB", {
        timeZone: "Europe/Berlin",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hourCycle: "h23"
    }).formatToParts(approx);

    const values = {};
    for (const p of formatted) {
        if (p.type !== "literal") values[p.type] = Number(p.value);
    }

    const shownAsUtc = Date.UTC(
        values.year,
        values.month - 1,
        values.day,
        values.hour,
        values.minute,
        values.second
    );

    return new Date(target - (shownAsUtc - target)).toISOString();
}

const start = berlinToUtc(year, month, day, 8);

// Folgetag bestimmen
const next = new Date(Date.UTC(year, month - 1, day + 1));
const end = berlinToUtc(
    next.getUTCFullYear(),
    next.getUTCMonth() + 1,
    next.getUTCDate(),
    8
);

msg.query = `SELECT SUM("rain_mm") AS "rain_today"
FROM "plantage_rain"
WHERE time >= '${start}' AND time < '${end}'`;

msg.topic = "precipitation/today";
msg.rain_period_start = start;
msg.rain_period_end = end;

return msg;

const rows = msg.payload;

let value = 0;

if (Array.isArray(rows) && rows.length > 0) {
    const result = Number(rows[0].rain_today);

    if (!Number.isFinite(result)) {
        node.warn("Ungültiger Tagesniederschlag");
        return null;
    }

    value = result;
} else {
    node.warn("Keine Messwerte für den Zeitraum – veröffentliche 0 mm");
}

msg.topic = "precipitation/today";
msg.payload = value;
msg.retain = true;

return msg;

msg.topic = "homeassistant/sensor/precipitation/today/config";

msg.payload = {
    name: "Plantage Niederschlag Heute MQTT",
    unique_id: "precipitation_today_mqtt",
    state_topic: "precipitation/today",
    unit_of_measurement: "mm",
    device_class: "precipitation",
    state_class: "measurement",
    value_template: "{{ value | float(1) }}",
    icon: "mdi:weather-rainy",
    device: {
        identifiers: ["plantage_niederschlagsmesser"],
        name: "Plantage Niederschlagsmesser",
        manufacturer: "Aqua-Scope",
        model: "RANLWE01"
    }
};

msg.retain = true;

return msg;

